          ..write('nCertificadoFgasEmpresa: $nCertificadoFgasEmpresa, ')
          ..write('logoRuta: $logoRuta, ')
          ..write('esDemo: $esDemo, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

