class Miembro extends DataClass implements Insertable<Miembro> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String empresaId;

  /// `auth.users`. Nulo en la demo local, que no tiene sesión.
  final String? userId;

  /// `admin|oficina|tecnico`.
  final String rol;
  final String nombre;
  final String? carneRite;

  /// Texto configurable (A1, A2, E, I.1, I.2…), no enum.
  final String? certFgasTipo;
  final String? certFgasNumero;
  final DateTime? certFgasCaduca;

  /// «JLM». Nula en quien no firma informes (oficina, admin). La unicidad
  /// por empresa la impone el servidor (ver `comunes.dart`).
  final String? serieInformes;
  final bool activo;
  const Miembro({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    required this.empresaId,
    this.userId,
    required this.rol,
    required this.nombre,
    this.carneRite,
    this.certFgasTipo,
    this.certFgasNumero,
    this.certFgasCaduca,
    this.serieInformes,
    required this.activo,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['empresa_id'] = Variable<String>(empresaId);
    if (!nullToAbsent || userId != null) {
      map['user_id'] = Variable<String>(userId);
    }
    map['rol'] = Variable<String>(rol);
    map['nombre'] = Variable<String>(nombre);
    if (!nullToAbsent || carneRite != null) {
      map['carne_rite'] = Variable<String>(carneRite);
    }
    if (!nullToAbsent || certFgasTipo != null) {
      map['cert_fgas_tipo'] = Variable<String>(certFgasTipo);
    }
    if (!nullToAbsent || certFgasNumero != null) {
      map['cert_fgas_numero'] = Variable<String>(certFgasNumero);
    }
    if (!nullToAbsent || certFgasCaduca != null) {
      map['cert_fgas_caduca'] = Variable<DateTime>(
        $MiembrosTable.$convertercertFgasCaducan.toSql(certFgasCaduca),
      );
    }
    if (!nullToAbsent || serieInformes != null) {
      map['serie_informes'] = Variable<String>(serieInformes);
    }
    map['activo'] = Variable<bool>(activo);
    return map;
  }

  MiembrosCompanion toCompanion(bool nullToAbsent) {
    return MiembrosCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      empresaId: Value(empresaId),
      userId: userId == null && nullToAbsent
          ? const Value.absent()
          : Value(userId),
      rol: Value(rol),
      nombre: Value(nombre),
      carneRite: carneRite == null && nullToAbsent
          ? const Value.absent()
          : Value(carneRite),
      certFgasTipo: certFgasTipo == null && nullToAbsent
          ? const Value.absent()
          : Value(certFgasTipo),
      certFgasNumero: certFgasNumero == null && nullToAbsent
          ? const Value.absent()
          : Value(certFgasNumero),
      certFgasCaduca: certFgasCaduca == null && nullToAbsent
          ? const Value.absent()
          : Value(certFgasCaduca),
      serieInformes: serieInformes == null && nullToAbsent
          ? const Value.absent()
          : Value(serieInformes),
      activo: Value(activo),
    );
  }

  factory Miembro.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Miembro(
      id: serializer.fromJson<String>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['created_at']),
      updatedAt: serializer.fromJson<DateTime>(json['updated_at']),
      empresaId: serializer.fromJson<String>(json['empresa_id']),
      userId: serializer.fromJson<String?>(json['user_id']),
      rol: serializer.fromJson<String>(json['rol']),
      nombre: serializer.fromJson<String>(json['nombre']),
      carneRite: serializer.fromJson<String?>(json['carne_rite']),
      certFgasTipo: serializer.fromJson<String?>(json['cert_fgas_tipo']),
      certFgasNumero: serializer.fromJson<String?>(json['cert_fgas_numero']),
      certFgasCaduca: $MiembrosTable.$convertercertFgasCaducan.fromJson(
        serializer.fromJson<Object?>(json['cert_fgas_caduca']),
      ),
      serieInformes: serializer.fromJson<String?>(json['serie_informes']),
      activo: serializer.fromJson<bool>(json['activo']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'created_at': serializer.toJson<DateTime>(createdAt),
      'updated_at': serializer.toJson<DateTime>(updatedAt),
      'empresa_id': serializer.toJson<String>(empresaId),
      'user_id': serializer.toJson<String?>(userId),
      'rol': serializer.toJson<String>(rol),
      'nombre': serializer.toJson<String>(nombre),
      'carne_rite': serializer.toJson<String?>(carneRite),
      'cert_fgas_tipo': serializer.toJson<String?>(certFgasTipo),
      'cert_fgas_numero': serializer.toJson<String?>(certFgasNumero),
      'cert_fgas_caduca': serializer.toJson<Object?>(
        $MiembrosTable.$convertercertFgasCaducan.toJson(certFgasCaduca),
      ),
      'serie_informes': serializer.toJson<String?>(serieInformes),
      'activo': serializer.toJson<bool>(activo),
    };
  }

  Miembro copyWith({
    String? id,
    DateTime? createdAt,
    DateTime? updatedAt,
    String? empresaId,
    Value<String?> userId = const Value.absent(),
    String? rol,
    String? nombre,
    Value<String?> carneRite = const Value.absent(),
    Value<String?> certFgasTipo = const Value.absent(),
    Value<String?> certFgasNumero = const Value.absent(),
    Value<DateTime?> certFgasCaduca = const Value.absent(),
    Value<String?> serieInformes = const Value.absent(),
    bool? activo,
  }) => Miembro(
    id: id ?? this.id,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
    empresaId: empresaId ?? this.empresaId,
    userId: userId.present ? userId.value : this.userId,
    rol: rol ?? this.rol,
    nombre: nombre ?? this.nombre,
    carneRite: carneRite.present ? carneRite.value : this.carneRite,
    certFgasTipo: certFgasTipo.present ? certFgasTipo.value : this.certFgasTipo,
    certFgasNumero: certFgasNumero.present
        ? certFgasNumero.value
        : this.certFgasNumero,
    certFgasCaduca: certFgasCaduca.present
        ? certFgasCaduca.value
        : this.certFgasCaduca,
    serieInformes: serieInformes.present
        ? serieInformes.value
        : this.serieInformes,
    activo: activo ?? this.activo,
  );
  Miembro copyWithCompanion(MiembrosCompanion data) {
    return Miembro(
      id: data.id.present ? data.id.value : this.id,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
      empresaId: data.empresaId.present ? data.empresaId.value : this.empresaId,
      userId: data.userId.present ? data.userId.value : this.userId,
      rol: data.rol.present ? data.rol.value : this.rol,
      nombre: data.nombre.present ? data.nombre.value : this.nombre,
      carneRite: data.carneRite.present ? data.carneRite.value : this.carneRite,
      certFgasTipo: data.certFgasTipo.present
          ? data.certFgasTipo.value
          : this.certFgasTipo,
      certFgasNumero: data.certFgasNumero.present
          ? data.certFgasNumero.value
          : this.certFgasNumero,
      certFgasCaduca: data.certFgasCaduca.present
          ? data.certFgasCaduca.value
          : this.certFgasCaduca,
      serieInformes: data.serieInformes.present
          ? data.serieInformes.value
          : this.serieInformes,
      activo: data.activo.present ? data.activo.value : this.activo,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Miembro(')
          ..write('id: $id, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('empresaId: $empresaId, ')
          ..write('userId: $userId, ')
          ..write('rol: $rol, ')
          ..write('nombre: $nombre, ')
          ..write('carneRite: $carneRite, ')
          ..write('certFgasTipo: $certFgasTipo, ')
          ..write('certFgasNumero: $certFgasNumero, ')
