    map['empresa_id'] = Variable<String>(empresaId);
    map['miembro_id'] = Variable<String>(miembroId);
    map['letra'] = Variable<String>(letra);
    map['registrado_at'] = Variable<DateTime>(registradoAt);
    map['ultimo_numero'] = Variable<int>(ultimoNumero);
    if (!nullToAbsent || ultimaSyncAt != null) {
      map['ultima_sync_at'] = Variable<DateTime>(ultimaSyncAt);
    }
    return map;
  }

  DispositivosCompanion toCompanion(bool nullToAbsent) {
    return DispositivosCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
