class Equipo extends DataClass implements Insertable<Equipo> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String empresaId;
  final String instalacionId;
  final TipoEquipo tipo;

  /// Nula hasta que el técnico confirma en T3 la que `fgas.dart` deduce de
  /// `tipo`: decide el art. 13.3 o el 13.4 y no debe inventarse.
  final CategoriaFgas? categoriaFgas;
  final String? marca;
  final String? modelo;
  final String? nSerie;
  final String? ubicacion;
  final DateTime? fechaInstalacion;
  final double? potenciaFrioKw;
  final double? potenciaCalorKw;
  final String? refrigerante;
  final double? cargaKg;
  final bool? hermeticoEtiquetado;
  final bool? deteccionFugas;
  final DateTime? deteccionUltimaRevision;
  final bool? etiquetaOk;

  /// Fechas anteriores a Inspecta, declaradas al dar de alta (opcionales).
  final DateTime? preventivoPrevioDeclarado;
  final DateTime? controlFugasPrevioDeclarado;

  /// `manual|placa_ia_confirmada`.
  final String origenDatos;

  /// Referencia blanda a `fotos.id`, sin clave foránea tampoco en Postgres:
  /// la foto de la placa nace después que el equipo y la coalescencia de la
  /// cola subiría el cambio antes que la foto (§8.2).
  final String? placaFotoId;

  /// `miembros.id` de quien confirmó los datos.
  final String? datosConfirmadosPor;
  final DateTime? datosConfirmadosAt;
  const Equipo({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.empresaId,
    required this.instalacionId,
    required this.tipo,
    this.categoriaFgas,
    this.marca,
    this.modelo,
    this.nSerie,
    this.ubicacion,
    this.fechaInstalacion,
    this.potenciaFrioKw,
    this.potenciaCalorKw,
    this.refrigerante,
    this.cargaKg,
    this.hermeticoEtiquetado,
    this.deteccionFugas,
    this.deteccionUltimaRevision,
    this.etiquetaOk,
    this.preventivoPrevioDeclarado,
    this.controlFugasPrevioDeclarado,
    required this.origenDatos,
    this.placaFotoId,
    this.datosConfirmadosPor,
    this.datosConfirmadosAt,
  });
  @override
