    }
    if (!nullToAbsent || refrigerante != null) {
      map['refrigerante'] = Variable<String>(refrigerante);
    }
    if (!nullToAbsent || cargaKg != null) {
      map['carga_kg'] = Variable<double>(cargaKg);
    }
    if (!nullToAbsent || hermeticoEtiquetado != null) {
      map['hermetico_etiquetado'] = Variable<bool>(hermeticoEtiquetado);
