class Plantilla extends DataClass implements Insertable<Plantilla> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String? empresaId;

  /// `split_hasta_12kw`…; única con `empresa_id` y `version` en el servidor.
  final String clave;
  final int version;
  final String titulo;
  final String? baseNormativa;

  /// jsonb: tipos, rango de potencia, uso.
  final String aplicaA;

  /// `borrador|publicada|retirada`.
  final String estado;

  /// `plantillas.id` de la versión anterior.
  final String? sustituyeA;
  final DateTime? publicadaAt;
  const Plantilla({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.empresaId,
    required this.clave,
    required this.version,
    required this.titulo,
    this.baseNormativa,
    required this.aplicaA,
    required this.estado,
    this.sustituyeA,
    this.publicadaAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || empresaId != null) {
      map['empresa_id'] = Variable<String>(empresaId);
    }
    map['clave'] = Variable<String>(clave);
    map['version'] = Variable<int>(version);
    map['titulo'] = Variable<String>(titulo);
    if (!nullToAbsent || baseNormativa != null) {
      map['base_normativa'] = Variable<String>(baseNormativa);
    }
    {
      map['aplica_a'] = Variable<String>(
        $PlantillasTable.$converteraplicaA.toSql(aplicaA),
      );
    }
    map['estado'] = Variable<String>(estado);
    if (!nullToAbsent || sustituyeA != null) {
      map['sustituye_a'] = Variable<String>(sustituyeA);
    }
    if (!nullToAbsent || publicadaAt != null) {
      map['publicada_at'] = Variable<DateTime>(publicadaAt);
    }
    return map;
  }

  PlantillasCompanion toCompanion(bool nullToAbsent) {
    return PlantillasCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      empresaId: empresaId == null && nullToAbsent
          ? const Value.absent()
          : Value(empresaId),
      clave: Value(clave),
      version: Value(version),
      titulo: Value(titulo),
      baseNormativa: baseNormativa == null && nullToAbsent
          ? const Value.absent()
          : Value(baseNormativa),
      aplicaA: Value(aplicaA),
      estado: Value(estado),
      sustituyeA: sustituyeA == null && nullToAbsent
          ? const Value.absent()
          : Value(sustituyeA),
      publicadaAt: publicadaAt == null && nullToAbsent
          ? const Value.absent()
          : Value(publicadaAt),
    );
  }

  factory Plantilla.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Plantilla(
      id: serializer.fromJson<String>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['created_at']),
      updatedAt: serializer.fromJson<DateTime>(json['updated_at']),
      empresaId: serializer.fromJson<String?>(json['empresa_id']),
      clave: serializer.fromJson<String>(json['clave']),
      version: serializer.fromJson<int>(json['version']),
      titulo: serializer.fromJson<String>(json['titulo']),
      baseNormativa: serializer.fromJson<String?>(json['base_normativa']),
      aplicaA: $PlantillasTable.$converteraplicaA.fromJson(
        serializer.fromJson<Object?>(json['aplica_a']),
      ),
      estado: serializer.fromJson<String>(json['estado']),
      sustituyeA: serializer.fromJson<String?>(json['sustituye_a']),
      publicadaAt: serializer.fromJson<DateTime?>(json['publicada_at']),
    );
