    }
    if (!nullToAbsent || plazoDias != null) {
      map['plazo_dias'] = Variable<int>(plazoDias);
    }
    map['para_equipo'] = Variable<bool>(paraEquipo);
    map['origen'] = Variable<String>(origen);
    if (!nullToAbsent || propuestaIaId != null) {
