class BlobLocal extends DataClass implements Insertable<BlobLocal> {
  final String id;

  /// Foto, nota, firma o informe.
  final String origenId;

  /// `original|pdf_1000|miniatura`. Solo `original` (y el PDF) se suben.
  final String variante;
  final Uint8List bytes;
  final String mime;
  final String sha256;
  final String? bucket;
  final String? ruta;

  /// Limpieza: lo subido y firmado con más de 14 días (salvo la miniatura).
  final DateTime? subidoAt;
  const BlobLocal({
    required this.id,
    required this.origenId,
    required this.variante,
    required this.bytes,
    required this.mime,
    required this.sha256,
    this.bucket,
    this.ruta,
    this.subidoAt,
  });
