    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['origen_id'] = Variable<String>(origenId);
    map['variante'] = Variable<String>(variante);
    map['bytes'] = Variable<Uint8List>(bytes);
    map['mime'] = Variable<String>(mime);
    map['sha256'] = Variable<String>(sha256);
    if (!nullToAbsent || bucket != null) {
      map['bucket'] = Variable<String>(bucket);
    }
    if (!nullToAbsent || ruta != null) {
      map['ruta'] = Variable<String>(ruta);
    }
    if (!nullToAbsent || subidoAt != null) {
      map['subido_at'] = Variable<DateTime>(subidoAt);
    }
    return map;
  }

  BlobsCompanion toCompanion(bool nullToAbsent) {
    return BlobsCompanion(
      id: Value(id),
      origenId: Value(origenId),
      variante: Value(variante),
      bytes: Value(bytes),
      mime: Value(mime),
      sha256: Value(sha256),
      bucket: bucket == null && nullToAbsent
          ? const Value.absent()
          : Value(bucket),
      ruta: ruta == null && nullToAbsent ? const Value.absent() : Value(ruta),
      subidoAt: subidoAt == null && nullToAbsent
          ? const Value.absent()
          : Value(subidoAt),
    );
  }

  factory BlobLocal.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return BlobLocal(
      id: serializer.fromJson<String>(json['id']),
      origenId: serializer.fromJson<String>(json['origen_id']),
      variante: serializer.fromJson<String>(json['variante']),
